internal sealed class EmbeddedCultureResourceManager : ResourceManager
{
    private const string Root = "StrmAssistantRebuild.Properties.Resources";
    private readonly ResourceManager neutral = new ResourceManager(Root, typeof(Resources).Assembly);
    private readonly ResourceManager simplified = new ResourceManager(Root + ".zh", typeof(Resources).Assembly);
    private readonly ResourceManager traditional = new ResourceManager(Root + ".zh-hant", typeof(Resources).Assembly);

    public EmbeddedCultureResourceManager() : base(Root, typeof(Resources).Assembly) { }

    private ResourceManager Route(CultureInfo? culture)
    {
        var name = (culture ?? CultureInfo.CurrentUICulture).Name.ToLowerInvariant();
        if (name == "zh-tw" || name == "zh-hk" || name == "zh-mo" || name == "zh-cht" ||
            name == "zh-hant" || name.StartsWith("zh-hant-", StringComparison.Ordinal)) return traditional;
        if (name == "zh" || name.StartsWith("zh-", StringComparison.Ordinal)) return simplified;
        return neutral;
    }

    public override string? GetString(string name) => GetString(name, null);
    public override string? GetString(string name, CultureInfo? culture) =>
        Route(culture).GetString(name, CultureInfo.InvariantCulture) ?? neutral.GetString(name, CultureInfo.InvariantCulture);
    public override object? GetObject(string name) => GetObject(name, null);
    public override object? GetObject(string name, CultureInfo? culture) =>
        Route(culture).GetObject(name, CultureInfo.InvariantCulture) ?? neutral.GetObject(name, CultureInfo.InvariantCulture);
    public override ResourceSet? GetResourceSet(CultureInfo culture, bool createIfNotExists, bool tryParents) =>
        Route(culture).GetResourceSet(CultureInfo.InvariantCulture, createIfNotExists, tryParents);
    public override void ReleaseAllResources()
    {
        neutral.ReleaseAllResources();
        simplified.ReleaseAllResources();
        traditional.ReleaseAllResources();
        base.ReleaseAllResources();
    }
}
